    ddcg_list_sir_node_t_ptr_t r_args = ddcg_list_sir_node_t_ptr_concat(no_args, ({ ddcg_list_sir_node_t_ptr_t _l = ddcg_list_sir_node_t_ptr_make(ctx->arena); _l = ddcg_list_sir_node_t_ptr_push(_l, sir_load_local(ctx->arena, t_r, prdt, NULL)); _l; }));
